<script setup lang="ts">
import {ref} from 'vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
interface Question {key:string;label:string;required:boolean;source:string;choices:string[]}
interface Template {id:number;parent_id:number|null;revision:number;version:number;title:string;questions:Question[];status:string}
interface Answer {key:string;answer:string;note:string}
interface Diagnostic {id:number;template_id:number;previous_id:number|null;revision:number;version:number;type:string;assessed_on:string;template_snapshot:{title:string;revision:number;questions:Question[]};answers:Answer[];status:string}
const props=defineProps<{missionId:number;active:boolean}>();const emit=defineEmits<{changed:[]}>()
const open=ref(false),editor=ref(false),busy=ref(false),lead=ref(false),error=ref(''),dialogError=ref(''),notice=ref(''),mode=ref('template'),decision=ref('submit'),confirmed=ref(false),requestKey=ref('')
const templates=ref<Template[]>([]),diagnostics=ref<Diagnostic[]>([]),model=ref<Template|null>(null),selected=ref<Diagnostic|null>(null),reading=ref<Diagnostic|null>(null),parentId=ref<number|null>(null)
const title=ref(''),questions=ref<Question[]>([]),templateId=ref(0),type=ref('initial'),assessedOn=ref(new Date().toLocaleDateString('sv-SE',{timeZone:'Africa/Porto-Novo'})),answers=ref<Record<string,{answer:string;note:string}>>({})
const labels:Record<string,string>={conform:'Conforme (déclaré)',gap:'Écart observé',not_applicable:'Non applicable',not_evaluated:'Non évalué'}
const statuses:Record<string,string>={draft:'Brouillon',published:'Publié',submitted:'Soumis, non partagé',shared:'Partagé'}
async function load(){busy.value=true;error.value='';try{const d=await request<{templates:Template[];diagnostics:Diagnostic[];can_lead:boolean}>(`/support/missions/${props.missionId}/diagnostics`);templates.value=d.templates;diagnostics.value=d.diagnostics;lead.value=d.can_lead}catch(e){templates.value=[];diagnostics.value=[];lead.value=false;reading.value=null;error.value=(e as Error).message}finally{busy.value=false}}
function init(value:string){mode.value=value;dialogError.value='';confirmed.value=false;requestKey.value=crypto.randomUUID();editor.value=true}
function templateEditor(t?:Template,revision=false){model.value=revision?null:t||null;parentId.value=revision?t!.id:null;title.value=t?.title||'';questions.value=t?JSON.parse(JSON.stringify(t.questions)):[];init('template')}
function addQuestion(){questions.value.push({key:crypto.randomUUID(),label:'',required:true,source:'',choices:Object.keys(labels)})}
function create(d?:Diagnostic){selected.value=d||null;templateId.value=d?.template_id||templates.value.find(t=>t.status==='published')?.id||0;type.value=d?.type||'initial';assessedOn.value=new Date().toLocaleDateString('sv-SE',{timeZone:'Africa/Porto-Novo'});init('new')}
function edit(d:Diagnostic){selected.value=d;answers.value=Object.fromEntries(d.template_snapshot.questions.map(q=>{const a=d.answers.find(a=>a.key===q.key);return [q.key,{answer:a?.answer||'',note:a?.note||''}]}));init('answers')}
function decide(value:string,d?:Diagnostic,t?:Template){selected.value=d||null;model.value=t||null;decision.value=value;init('decision')}
async function save(){busy.value=true;dialogError.value='';let path=`/support/missions/${props.missionId}/diagnostics`,method='POST';let body:Record<string,unknown>={confirmed:confirmed.value};try{
 if(mode.value==='template'){path+='/templates';if(model.value){path+='/'+model.value.id;method='PATCH'}body={...body,title:title.value,questions:questions.value,...(model.value?{version:model.value.version}:{request_key:requestKey.value,parent_id:parentId.value})}}
 if(mode.value==='new')body={...body,template_id:templateId.value,type:type.value,assessed_on:assessedOn.value,request_key:requestKey.value,...(selected.value?{previous_id:selected.value.id}:{})}
 if(mode.value==='answers'){path+='/'+selected.value!.id;method='PATCH';body={version:selected.value!.version,answers:Object.entries(answers.value).filter(([,a])=>a.answer).map(([key,a])=>({key,...a}))}}
 if(mode.value==='decision'){if(decision.value==='publish'){path+=`/templates/${model.value!.id}/publish`;body={...body,version:model.value!.version}}else{path+=`/${selected.value!.id}/decision`;body={...body,version:selected.value!.version,action:decision.value}}}
 await request(path,method,body);notice.value='Opération enregistrée. Seules les versions partagées sont visibles à l’officine.';await load();editor.value=false;emit('changed')
 }catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><button class="button secondary" @click="open=true;load()">Diagnostics & modèles</button>
<AppModal v-model="open" title="Diagnostics versionnés" :busy="busy" size="wide"><div class="form-body"><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><p class="module-disclaimer">Aucun score ni grille réglementaire préremplie. Les réponses sont des constats déclarés, pas une certification. Le modèle publié est figé pour chaque diagnostic.</p><div v-if="lead&&active" class="heading-actions"><button class="button secondary" @click="templateEditor()">Créer un modèle</button><button class="button primary" :disabled="!templates.some(t=>t.status==='published')" @click="create()">Créer un diagnostic</button></div><h3>Modèles de cette mission</h3><p v-if="!templates.length">Aucun modèle configuré ou publié dans votre périmètre.</p><article v-for="t in templates" :key="t.id" class="detail-card"><strong>{{t.title}} · révision {{t.revision}}</strong><p>{{statuses[t.status]}} · {{t.questions.length}} question(s)</p><div v-if="lead&&active" class="heading-actions"><template v-if="t.status==='draft'"><button class="button secondary small" @click="templateEditor(t)">Modifier le modèle</button><button class="button primary small" @click="decide('publish',undefined,t)">Publier le modèle</button></template><button v-else class="button secondary small" @click="templateEditor(t,true)">Préparer une nouvelle version du modèle</button></div></article><h3>Diagnostics</h3><p v-if="!diagnostics.length">Aucun diagnostic visible. Les brouillons ne sont pas retournés à l’officine.</p><article v-for="d in diagnostics" :key="d.id" class="detail-card"><strong>{{d.template_snapshot.title}} · {{d.type==='initial'?'Initial':'Suivi'}} · {{d.assessed_on}}</strong><p>Modèle r{{d.template_snapshot.revision}} · diagnostic r{{d.revision}} · {{statuses[d.status]}}</p><div class="heading-actions" style="flex-wrap:wrap"><button class="button secondary small" @click="reading=d">Voir le diagnostic</button><template v-if="lead&&active"><button v-if="d.status==='draft'" class="button secondary small" @click="edit(d)">Renseigner les réponses</button><button v-if="d.status==='draft'" class="button primary small" @click="decide('submit',d)">Soumettre le diagnostic</button><button v-if="d.status==='submitted'" class="button primary small" @click="decide('share',d)">Partager le diagnostic</button><button v-if="d.status==='shared'" class="button secondary small" @click="create(d)">Préparer une révision du diagnostic</button></template></div></article></div><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Fermer</button></template></AppModal>
<AppModal v-model="editor" :title="mode==='template'?'Modèle de diagnostic':mode==='new'?'Créer un diagnostic':mode==='answers'?'Réponses du diagnostic':decision==='publish'?'Publier le modèle ?':decision==='share'?'Partager le diagnostic ?':'Soumettre le diagnostic ?'" :busy="busy" size="wide"><form id="mission-diagnostic-form" class="form-body correction-form" @submit.prevent="save"><p v-if="dialogError" class="alert error" role="alert">{{dialogError}}</p><template v-if="mode==='template'"><label>Titre du modèle<input v-model="title" required maxlength="180"/></label><p>Définissez vos propres questions et leurs sources. Aucun barème n’est calculé. Une source externe doit être vérifiée avant publication.</p><fieldset v-for="(q,index) in questions" :key="q.key" class="detail-card"><legend>Question {{index+1}}</legend><label>Libellé<input v-model="q.label" required maxlength="1000"/></label><label>Source, version et date de vérification<textarea v-model="q.source" maxlength="1500"/></label><label class="checkbox-label"><input v-model="q.required" type="checkbox"/>Réponse obligatoire à la soumission</label><div><span>Réponses autorisées</span><label v-for="(label,key) in labels" :key="key" class="checkbox-label"><input v-model="q.choices" type="checkbox" :value="key"/>{{label}}</label></div><button type="button" class="text-link" @click="questions.splice(index,1)">Retirer la question du brouillon</button></fieldset><button type="button" class="button secondary" :disabled="questions.length>=60" @click="addQuestion">Ajouter une question</button></template>
<template v-else-if="mode==='new'"><label>Modèle publié<select v-model="templateId" required :disabled="!!selected"><option :value="0" disabled>Choisir un modèle publié</option><option v-for="t in templates.filter(t=>t.status==='published')" :key="t.id" :value="t.id">{{t.title}} · r{{t.revision}}</option></select></label><label>Type<select v-model="type" :disabled="!!selected"><option value="initial">Initial</option><option value="followup">Suivi</option></select></label><label>Date d’évaluation<input v-model="assessedOn" type="date" required/></label><p v-if="selected">Une nouvelle révision conserve le même modèle et reprend les réponses précédentes sans modifier la version partagée.</p></template>
<template v-else-if="mode==='answers'&&selected"><fieldset v-for="q in selected.template_snapshot.questions" :key="q.key" class="detail-card"><legend>{{q.label}}{{q.required?' *':''}}</legend><p v-if="q.source" class="module-disclaimer">Source : {{q.source}}</p><label>Réponse<select v-model="answers[q.key].answer"><option value="">Non renseignée</option><option v-for="choice in q.choices" :key="choice" :value="choice">{{labels[choice]}}</option></select></label><label>{{answers[q.key].answer==='not_applicable'?'Justification obligatoire':'Commentaire factuel'}}<textarea v-model="answers[q.key].note" :required="answers[q.key].answer==='not_applicable'" maxlength="3000" rows="3"/></label></fieldset><p>Le brouillon peut être incomplet. « Non évalué » reste distinct de « Conforme ». Ne saisissez aucune note interne dans les champs destinés à être partagés.</p></template>
<template v-else><p>{{decision==='publish'?'La publication fige cette version du modèle. Toute modification future crée une nouvelle version.':decision==='share'?'Cette version sera visible à l’officine. Vérifiez son contenu avant publication.':'La soumission vérifie les réponses obligatoires puis fige cette version. Elle ne la partage pas encore.'}}</p></template><label v-if="mode!=='answers'" class="checkbox-label"><input v-model="confirmed" required type="checkbox"/>Je confirme cette opération sans présumer d’une conformité réglementaire.</label></form><template #footer><button class="button secondary" :disabled="busy" @click="editor=false">Annuler</button><button class="button primary" :disabled="busy" form="mission-diagnostic-form" type="submit">{{mode==='answers'?'Enregistrer le brouillon':'Confirmer'}}</button></template></AppModal>
<AppModal :model-value="!!reading" title="Diagnostic · version figée du modèle" size="wide" @update:model-value="reading=null"><div v-if="reading" class="form-body"><h3>{{reading.template_snapshot.title}}</h3><p>Modèle r{{reading.template_snapshot.revision}} · diagnostic r{{reading.revision}} · {{statuses[reading.status]}}</p><article v-for="q in reading.template_snapshot.questions" :key="q.key" class="detail-card"><strong>{{q.label}}</strong><p>{{labels[reading.answers.find(a=>a.key===q.key)?.answer||'']||'Non renseignée'}}</p><p style="white-space:pre-wrap">{{reading.answers.find(a=>a.key===q.key)?.note||'—'}}</p><small v-if="q.source">Source : {{q.source}}</small></article><p class="module-disclaimer">Aucun score de conformité ni comparaison automatique entre grilles différentes.</p></div><template #footer><button class="button secondary" @click="reading=null">Fermer</button></template></AppModal></template>
